// Every module the editor page imports, directly or through another module, must be served: the server only hands
// out an allowlist, so a new file left off it would stop the whole editor from starting.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createServer } from './serve.mjs';

function imports(file, seen = new Set()) {
  if (seen.has(file)) return seen;
  seen.add(file);
  // Generated by the server from the plugin's icon table: there is no file to read.
  if (file === 'item-icons.mjs') return seen;
  const source = readFileSync(new URL(`./${file}`, import.meta.url), 'utf8');
  for (const m of source.matchAll(/(?:import\s[^'"]*?from\s*|import\(\s*)['"]\.\/([a-z0-9-]+\.mjs)['"]/g)) imports(m[1], seen);
  return seen;
}

test('the editor server serves every module the page loads', async () => {
  const modules = [...imports('app.mjs')];
  assert.ok(modules.includes('expressions.mjs') && modules.includes('icon-library.mjs'), modules.join(', '));
  const server = createServer();
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  try {
    for (const file of modules) {
      // item-icons.mjs is generated from the plugin's table at run time; the page works without it.
      if (file === 'item-icons.mjs') continue;
      assert.equal((await fetch(`${base}/${file}`, { method: 'HEAD' })).status, 200, file);
    }
  } finally { await new Promise(resolve => server.close(resolve)); }
});
